import{_ as a,o as e,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2020-01-16 -- Ceph Performance Meeting","description":"","frontmatter":{"title":"2020-01-16 -- Ceph Performance Meeting","date":"2020-01-16T00:00:00.000Z","updated":"2020-01-24T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","自动缩放","CRUSH 算法"],"categories":["会议纪要"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-01-16_-_-_Ceph_Performance_Meeting.md","filePath":"posts/2020/2020-01-16_-_-_Ceph_Performance_Meeting.md","lastUpdated":1780460162000}'),r={name:"posts/2020/2020-01-16_-_-_Ceph_Performance_Meeting.md"};function o(n,l,s,u,h,p){return e(),i("div",null,[...l[0]||(l[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间" tabindex="-1">会议时间 <a class="header-anchor" href="#会议时间" aria-label="Permalink to &quot;会议时间&quot;">​</a></h4><ul><li>日期：2020年1月16日</li><li>时长：约1小时</li></ul><h4 id="参会人员" tabindex="-1">参会人员 <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员&quot;">​</a></h4><ul><li>主要参与者：Josh, Stage, Alex 以及其他未提及的核心成员</li></ul><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>Ceph Balancer相关讨论</strong></p><ul><li>审查并行CRUSH计算的PR。</li><li>关闭了使用MS基础设施的balancer PR。</li><li>讨论了与manager相关的性能问题。</li></ul></li><li><p><strong>硬件推荐文档更新</strong></p><ul><li>更新文档，特别是关于透明大页（THP）的设置。</li></ul></li><li><p><strong>PG（放置组）相关讨论</strong></p><ul><li>增加默认的PG数量到11。</li><li>测试并调整PG log长度。</li></ul></li><li><p><strong>Autoscaler测试结果</strong></p><ul><li>Alex分享了在OpenShift中使用Steph的测试结果，发现数据分布不均的问题。</li><li>通过调整目标比率和启用PG balancer，数据分布得到了改善。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ol><li><p><strong>不缩减PG数量，除非有压力</strong></p><ul><li>避免过早缩减PG数量，以保持数据分布的均匀性。</li></ul></li><li><p><strong>自动选择PG log长度</strong></p><ul><li>根据PG数量自动选择PG log长度，以优化内存使用。</li></ul></li><li><p><strong>增加默认PG数量</strong></p><ul><li>增加默认的PG数量，以改善初始数据分布和性能。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ol><li><p><strong>审查并行crush计算的PR</strong></p><ul><li>确保相关PR得到及时审查和合并。</li></ul></li><li><p><strong>更新硬件推荐文档</strong></p><ul><li>根据最新版本和最佳实践更新文档。</li></ul></li><li><p><strong>进一步测试PG相关设置</strong></p><ul><li>继续测试PG数量和PG log长度的最佳配置，以优化性能和数据分布。</li></ul></li><li><p><strong>跟踪Autoscaler的进一步优化</strong></p><ul><li>根据测试结果和用户反馈，进一步优化Autoscaler的性能和功能。</li></ul></li></ol><h4 id="其他讨论" tabindex="-1">其他讨论 <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论&quot;">​</a></h4><ul><li>讨论了PG balancer的性能影响和潜在的改进方向。</li><li>讨论了PG数量对恢复速度的影响，以及如何平衡性能和数据安全性。</li></ul><h4 id="下次会议" tabindex="-1">下次会议 <a class="header-anchor" href="#下次会议" aria-label="Permalink to &quot;下次会议&quot;">​</a></h4><ul><li>预计下周同一时间再次召开会议，讨论进一步的进展和问题。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><ul><li>会议在约1小时后结束，参与者表示感谢并期待下次会议。</li></ul>',17)])])}const _=a(r,[["render",o]]);export{d as __pageData,_ as default};
